    (LOWER(status) == 'success') &
    (YEAR(date_time) == 2023) &
    ISIN(MONTH(date_time), (1, 2, 3))
).CALCULATE(
    transaction_month=MONTH(date_time)
).PARTITION(
    name="monthly_transactions", by=(transaction_month)
).CALCULATE(
    month=transaction_month,
    average_price=AVG(Transactions.price)
).ORDER_BY(month.ASC())

