code:
daily_payment_summary = Dealership.CALCULATE(
    start_of_current_week=DATETIME('now', 'start of week')
).CALCULATE(
    start_of_previous_week=DATETIME(start_of_current_week, '-7 days')
).PaymentsReceived.WHERE(
    (payment_date >= start_of_previous_week) & (payment_date < start_of_current_week)
).PARTITION(
    name="daily_groups", by=(payment_date, payment_method)
).CALCULATE(
    payment_day=payment_date,
    payment_type=payment_method,
    total_amount=SUM(PaymentsReceived.payment_amount)
).ORDER_BY(payment_day.ASC(), payment_type.ASC())

